head.script:
scwin.gVar = {
    "bReady" : false,
}



// 테스트 설명, 유효성 값 설정
//  - 이벤트 발생 순서 축(마우스 / Tab / Enter 포커스 해제)을 담당한다.
//  - 발생 조건(포커스 해제 / setValue / 값 변경 없음 / Enter) 과 info 파라미터는 secret_E_onviewchange_1.xml, ref 바인딩 데이터 선택 변경은 secret_E_onviewchange_2.xml 에서 검증한다.
//  - onkeydown, onkeypress, onkeyup, onchange, onblur 는 순서 확인용 출력으로만 사용한다.
scwin.tData = {
    "description" : "[secret > E > onviewchange]<br/>Secret 컴포넌트에서 사용자의 조작에 의해 입력값이 변경된 후 포커스가 해제될때 발생합니다.",
    "validation" : [
        "마우스에 의한 포커스 해제 시 'onchange > onviewchange > onblur' 순서로 이벤트가 발생합니다.",
        "Tab 키로 포커스 해제 시 'onkeydown > onchange > onviewchange > onblur' 순서로 이벤트가 발생합니다.",
        "Enter 키 입력 시 'onkeydown > onkeypress > onkeyup > onchange > onviewchange > onblur' 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 생성 중 헬퍼의 초기값 설정으로 발생하는 onchange 는 출력하지 않음
    scwin.gVar["bReady"] = false;

    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 생성 직후 초기값 secret 이 설정됩니다\n[절차] 결과창 clear -> target1 클릭 -> 값 입력 -> 아래 중 하나로 포커스 해제 (clear 버튼 클릭 자체가 포커스 해제이므로 반드시 입력 전에 clear 합니다)\n - 마우스 : 바깥 영역 클릭\n - Tab : Tab 키 입력\n - Enter : Enter 키 입력\n[확인] 결과창에 출력된 이벤트 줄의 순서 (각 이벤트는 발생 즉시 한 줄씩 출력)\n값 입력 중 발생한 onkeydown, onkeypress, onkeyup 줄이 먼저 나오고 그 뒤에 포커스 해제 시점의 순서가 이어집니다"', '', 'label1');

    let eList = $c.gcm.createEList(["onkeydown", "onkeypress", "onkeyup", "onchange", "onviewchange", "onblur"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret('', eList);

    scwin.gVar["bReady"] = true;
}



// validation 1, 2, 3 판정 출력 (각 핸들러 발생 즉시 한 줄 출력 = 출력 순서가 실제 발생 순서)
scwin.target1_onkeydown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onkeydown");
}



scwin.target1_onkeypress = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onkeypress");
}



scwin.target1_onkeyup = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onkeyup");
}



scwin.target1_onchange = function (info) {
    if (!scwin.gVar["bReady"])
        return;

    wf_body_bottom.getObj("scwin").setReturnValue("▶ onchange");
}



scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onviewchange");
}



scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onblur");
}
